import { Chart } from 'chart.js';

export interface CustomGridProps {
  display?: boolean;
  color?: string;
  width?: number;
  horizontalGridEnd?: 'chartWidth' | 'xAxisRight';
  horizontalGridEndOffset?: number;
}

const defaultConfig: CustomGridProps = {
  display: true,
  color: '#E4E7EA',
  width: 1,
};

export const CustomGrid = {
  id: 'customGrid',
  beforeDraw: (chart: Chart) => {
    const ctx = chart.ctx;
    const xAxis = chart.scales['x'];
    const yAxis = chart.scales['y'];
    const indexAxis = chart.config.options?.indexAxis;

    const config: CustomGridProps =
      chart.config.options?.plugins?.customGrid ?? {};

    if (config.display === false) return;

    if (!xAxis || !yAxis) return;

    ctx.save();
    ctx.strokeStyle = config.color ?? defaultConfig.color ?? '#E4E7EA';
    ctx.lineWidth = config.width ?? defaultConfig.width ?? 1;

    if (indexAxis === 'x') {
      const horizontalEndOffset = config.horizontalGridEndOffset ?? 0;
      const horizontalEnd =
        config.horizontalGridEnd === 'xAxisRight'
          ? xAxis.right + horizontalEndOffset
          : chart.width;

      yAxis.ticks.forEach((tick, i) => {
        const y = yAxis.getPixelForTick(i);
        ctx.beginPath();
        ctx.moveTo(xAxis.left, y);
        ctx.lineTo(horizontalEnd, y);
        ctx.stroke();
      });
    }

    if (indexAxis === 'y') {
      xAxis.ticks.forEach((tick, i) => {
        const x = xAxis.getPixelForTick(i);
        ctx.beginPath();
        ctx.moveTo(x, yAxis.top);
        ctx.lineTo(x, yAxis.bottom);
        ctx.stroke();
      });
    }

    ctx.restore();
  },
};
